#pragma once
#include <cstring>
namespace Tab5Shell {
struct HelpEntry {const char* command;const char* syntax;const char* description;const char* example;};
// Syntax/examples remain literal commands. Descriptions are independent
// translation keys, shared by the index, detailed help and argument errors.
inline constexpr HelpEntry helpEntries[]={
 {"serial","serial [status | port usb|rs485 | mode debug|data | baud 1200..921600 | frame 8N1|8E1|8O1|8N2 | ending none|lf|crlf | send TEXT | write [TEXT] | read [BYTES [MS]] | listen [MS] | clear]","Configure le port série. USB-C utilise le périphérique USB Serial/JTAG ; RS485 utilise le connecteur intégré. send ajoute la fin de ligne choisie, write conserve les octets et accepte un tube ou un fichier en entrée. read reçoit des octets ; listen écoute pendant 60 secondes par défaut. Ctrl+C interrompt. clear vide les files. Les paramètres sont mémorisés ; débit et format ne concernent que RS485.","serial mode data; serial send Bonjour; serial read 4096 1000 > reception.txt"},
 {"git","git [-C DIR] COMMAND [ARGS...]","Git : init dossier ; status ; add -A ou add -- fichier ; commit -m message ; log -n nombre ; diff [--cached]. clone [--depth nombre] [--credential-file fichier] URL dossier importe par HTTPS. fetch [remote], pull --ff-only [remote], push [remote]. remote set-url origin URL règle la source. config user.name|user.email|tab5.credentialFile|tab5.usernameSecret|tab5.tokenSecret [valeur]. -C dossier change le projet pour cette commande. Les références usernameSecret et tokenSecret lisent le coffre déverrouillé lors de l’authentification. clone accepte --username-secret NOM --token-secret NOM. Le fichier d’identification reste compatible. config --unset CLE retire une référence.","git init sd:/Projects/demo"},
 {"ssh","ssh [-p PORT] (-i KEY | --password-file FILE) [--passphrase-file FILE] [--timeout SECONDS] USER@HOST COMMAND... | ssh keyscan [-p PORT] HOST | ssh trust [-p PORT] HOST SHA256:... | ssh forget [-p PORT] HOST","Exécute une commande distante chiffrée. Vérifiez l'empreinte du serveur avant ssh trust. Clé privée PEM RSA/ECDSA ou fichier secret ; jamais de mot de passe en argument. Les tubes transportent stdin et stdout. Pas de terminal interactif PTY. --timeout règle le délai sans données de 1 à 3600 secondes ; 30 par défaut.","ssh -i sd:/Keys/id_ecdsa user@192.168.1.20 'uname -a'"},
 {"sftp","sftp get|put [-p PORT] (-i KEY | --password-file FILE) [--passphrase-file FILE] [--timeout SECONDS] USER@HOST REMOTE LOCAL | sftp ls [OPTIONS] USER@HOST REMOTE","Transfère un fichier ou liste un dossier distant via SSH. La confiance du serveur se règle avec ssh trust. get reçoit vers LOCAL ; put envoie LOCAL vers REMOTE. Les fichiers existants ne sont pas écrasés. Transfert progressif, annulable avec Ctrl+C.","sftp get -i sd:/Keys/id_ecdsa user@192.168.1.20 /home/user/data.txt sd:/Documents/data.txt"},
 {"tasks","tasks","Affiche les tâches réelles : identifiant, nom OS, état, priorité, minimum de pile libre en octets et compteur d'exécution. États : 0 en cours, 1 prête, 2 bloquée, 3 suspendue, 4 supprimée, 5 inconnu. sdk désigne une tâche du système de base.","tasks"},
 {"help","help [COMMAND]","Liste les commandes ; ajoutez un nom pour ses paramètres et un exemple.","help wget"},
 {"pwd","pwd","Affiche le dossier courant.","pwd"},
 {"cd","cd [DIR]","Change de dossier. Sans paramètre : racine SD. .. désigne le parent ; /USB désigne le disque USB.","cd /USB/Documents"},
 {"ls","ls [-a] [-l] [DIR]","Liste le dossier courant ou indiqué. -a inclut les fichiers cachés ; -l affiche le type et la taille.","ls -al /Documents"},
 {"tree","tree [DIR]","Liste tous les chemins du dossier et de ses sous-dossiers, jusqu'à 16 niveaux.","tree /Documents"},
 {"stat","stat FILE...","Affiche le type, la taille en octets et la date de modification de chaque chemin.","stat /Documents/notes.txt"},
 {"du","du [DIR]","Calcule la taille des fichiers d'un dossier, sous-dossiers et fichiers cachés inclus.","du /Documents"},
 {"cat","cat [FILE...]","Affiche les fichiers texte dans l'ordre indiqué.","cat notes.txt"},
 {"head","head [-n COUNT] [FILE...]","Affiche les premières lignes. -n : de 1 à 500 lignes ; 10 par défaut.","head -n 20 notes.txt"},
 {"tail","tail [-n COUNT] [FILE...]","Affiche les dernières lignes. -n : de 1 à 500 lignes ; 10 par défaut. Maximum conservé : 64 Kio.","tail -n 30 journal.txt"},
 {"wc","wc [-lwc] [FILE...]","Compte les sauts de ligne, mots et octets. -l, -w et -c choisissent les compteurs ; sans fichier, lit le tube.","wc notes.txt"},
 {"grep","grep [-i] [-n] TEXT [FILE...]","Cherche un texte littéral. -i ignore la casse ASCII ; -n affiche les numéros de ligne. Aucun résultat : code 1.","grep -in erreur journal.txt"},
 {"find","find [DIR] [-name PATTERN]","Cherche récursivement jusqu'à 16 niveaux. -name filtre le nom ; placez les motifs entre apostrophes.","find /Documents -name '*.txt'"},
 {"hexdump","hexdump [-n BYTES] [-s OFFSET] FILE","Affiche octets hexadécimaux et texte. -n : 1 à 65536 octets, 256 par défaut ; -s : position de départ en octets.","hexdump -n 64 -s 16 image.bin"},
 {"cmp","cmp FILE1 FILE2","Compare deux fichiers, indique le premier octet différent et renvoie 1 s'ils diffèrent.","cmp original.bin copie.bin"},
 {"mkdir","mkdir [-p] DIR...","Crée les dossiers. -p crée aussi les parents manquants et accepte un dossier déjà présent.","mkdir -p /Documents/Projet"},
 {"rmdir","rmdir DIR...","Supprime uniquement des dossiers vides. La racine d'un support reste protégée.","rmdir /Documents/Vide"},
 {"touch","touch FILE...","Crée un fichier vide s'il n'existe pas ; conserve le contenu d'un fichier existant.","touch notes.txt"},
 {"cp","cp SOURCE DEST","Copie un fichier vers un fichier ou dossier. L'ancienne destination reste intacte si la copie échoue.","cp notes.txt /USB/Documents"},
 {"mv","mv SOURCE DEST","Déplace ou renomme un fichier ou dossier sur le même support. Refuse d'écraser une destination existante.","mv brouillon.txt notes.txt"},
 {"rm","rm [-r] PATH...","Supprime immédiatement les chemins. -r inclut le contenu des dossiers. La racine d'un support reste protégée.","rm brouillon.txt"},
 {"basename","basename PATH","Affiche le dernier composant d'un chemin.","basename /Documents/notes.txt"},
 {"dirname","dirname PATH","Affiche le dossier parent d'un chemin.","dirname /Documents/notes.txt"},
 {"echo","echo [-n] TEXT...","Affiche les paramètres séparés par des espaces. -n omet le saut de ligne final.","echo 'Bonjour' > notes.txt"},
 {"printf","printf FORMAT [TEXT...]","Affiche un format : %s insère un paramètre, %% un pourcentage, \\n un saut de ligne et \\t une tabulation.","printf '%s\\n' Bonjour"},
 {"seq","seq [START] END","Affiche une suite d'entiers croissants, un par ligne. Début : 1 par défaut ; maximum : 10000 valeurs.","seq 3 8"},
 {"clear","clear","Efface l'affichage du terminal ; conserve l'historique et les variables.","clear"},
 {"set","set NAME VALUE","Définit une variable ; nom=valeur est aussi accepté. Utilisez $nom ou ${nom}. Maximum : 32 variables.","set dossier /Documents"},
 {"export","export NAME=VALUE | export --secret NAME [KEY]","Partage une variable publique en mémoire jusqu’au redémarrage ; --secret lie un nom à une entrée chiffrée du coffre, résolue seulement lorsque le coffre est déverrouillé.","export --secret GIT_TOKEN"},
 {"unset","unset NAME","Supprime une variable.","unset dossier"},
 {"env","env","Liste uniquement les noms des variables. Pour lire volontairement une valeur, utilisez echo \"$NOM\".","env"},
 {"test","test -e PATH | -f PATH | -d PATH | TEXT = TEXT | TEXT != TEXT","Teste une existence (-e), un fichier (-f), un dossier (-d) ou deux textes. Résultat vrai : 0 ; faux : 1.","test -f notes.txt && cat notes.txt"},
 {"true","true","Renvoie le code 0 ; utile dans les conditions de scripts.","true && echo oui"},
 {"false","false","Renvoie le code 1 ; utile dans les conditions de scripts.","false || echo non"},
 {"source","source FILE.sh [ARGS...]","Exécute un script dans le terminal courant. $0 à $9 contiennent son chemin et ses paramètres. Taille maximale : 32 Kio.","source /Scripts/sauvegarde.sh /Documents"},
 {"sh","sh FILE.sh [ARGS...]","Exécute un script dans le terminal courant, comme source. Les changements de dossier et de variables persistent.","sh /Scripts/sauvegarde.sh /Documents"},
 {"for","for NAME in VALUES; do COMMANDS; done","Répète les commandes pour chaque valeur. Maximum : 4 niveaux de scripts ou boucles et 10000 commandes par lancement.","for f in /Documents/*.txt; do wc \"$f\"; done"},
 {"date","date","Affiche la date et l'heure de l'OS.","date"},
 {"df","df [DIR]","Affiche l'espace libre et la capacité du support contenant le dossier ; dossier courant par défaut.","df /USB"},
 {"memory","memory","Affiche la mémoire disponible et le plus grand bloc allouable.","memory"},
 {"uptime","uptime","Affiche les secondes écoulées depuis le démarrage.","uptime"},
 {"sleep","sleep SECONDS","Attend une durée de 0 à 3600 secondes ; les fractions utilisent un point. Ctrl+C interrompt l'attente.","sleep 0.5"},
 {"sha256","sha256 FILE...","Calcule l'empreinte SHA-256 de chaque fichier, sur SD ou USB.","sha256 /USB/firmware.bin"},
 {"wifi","wifi","Affiche le nom du réseau et l'adresse IPv4, ou l'état déconnecté.","wifi"},
 {"netinfo","netinfo","Affiche le réseau Wi-Fi, IPv4, masque, passerelle, DNS et signal. Alias : ifconfig, ip addr, ip route.","netinfo"},
 {"ifconfig","ifconfig","Alias de netinfo : affiche la configuration réseau actuelle.","ifconfig"},
 {"ip","ip [addr|route]","Affiche IPv4, masque, passerelle et DNS. La modification des routes n'est pas disponible.","ip route"},
 {"dns","dns HOST","Résout un nom DNS en IPv4, avec un délai maximal de 5 secondes. Alias : nslookup.","dns example.org"},
 {"nslookup","nslookup HOST","Alias de dns : résout un nom DNS en IPv4.","nslookup example.org"},
 {"ping","ping [-c COUNT] [-W SECONDS] HOST","Teste les réponses ICMP. -c : 1 à 100 requêtes, 4 par défaut ; -W : attente par requête, 1 seconde par défaut.","ping -c 3 -W 0.5 192.168.1.1"},
 {"tcp","tcp [-w SECONDS] HOST PORT","Teste l'ouverture d'un port TCP sans envoyer de données. Port : 1 à 65535 ; -w : délai de connexion, 1.5 seconde par défaut.","tcp -w 2 example.org 443"},
 {"nc","nc [-z] [-w SECONDS] HOST PORT","Alias de tcp. -z teste la connexion sans envoyer de données. Ce client ne crée pas de session interactive.","nc -z -w 2 192.168.1.1 80"},
 {"ports","ports [-w SECONDS] HOST PORTS","Teste les ports d'un appareil. Liste : 22,80,443 ou 8000-8010 ; maximum 1024 ports. -w : délai par port, 1.5 seconde par défaut.","ports -w 0.35 192.168.1.1 22,80,443,8000-8010"},
 {"headers","headers [-L] [-T SECONDS] URL","Affiche statut HTTP, certificat HTTPS vérifié et en-têtes utiles à l'audit. -L suit 5 redirections au maximum ; -T limite la durée totale de 1 à 3600 secondes, 120 par défaut.","headers -L https://example.org"},
 {"wget","wget [-O FILE] [-L] [-T SECONDS] [--overwrite] URL","Télécharge sur SD ou USB. -O choisit le fichier ; sinon le nom vient de l'URL. -L suit les redirections ; -T limite la durée totale de 1 à 3600 secondes (120 par défaut). --overwrite remplace un fichier après réussite.","wget -L -O usb:/Documents/page.html https://example.org"},
 {"curl","curl [-I] [-o FILE|-O] [-L] [-T SECONDS] [--overwrite] URL","Affiche une réponse HTTP (32 Kio maximum), ou l'enregistre avec -o fichier ou -O (nom de l'URL). -I demande les en-têtes ; -L suit les redirections ; -T limite la durée totale de 1 à 3600 secondes, 120 par défaut. HTTPS vérifie certificat et nom d'hôte.","curl -L -o sd:/Documents/page.html https://example.org"}
};
inline const HelpEntry* helpEntry(const char* command){for(const auto& entry:helpEntries)if(!strcmp(command,entry.command))return &entry;return nullptr;}
}
